    def _draw_spectrum_radar(self, fig, p, snap):
        """Pass 93: REAL spectrum-as-radar view (no coherent IQ attached). Everything here is
        derived from genuinely-measured RSSI across the carriers; nothing is fabricated."""
        cnt  = int(p.get("df_source_count", 0)) if p else 0
        valid = bool(p.get("rf_corr_valid", False)) if p else False
        lf   = p.get("live_feed", {}) if p else {}
        fig.suptitle(
            f"SPECTRUM-AS-RADAR (carrier bounces, magnitude domain) — REAL   ·   "
            f"device-free movers: {cnt if valid else '—'}   ·   "
            f"{lf.get('carriers_tracked', 0)} carriers @ {lf.get('sample_rate_hz', 0):.0f} Hz",
            color='#00ffcc', fontsize=12, fontweight='bold')

        # Panel 1 — device-free RANGE profile (real: motion vs distance) + targets
        ax1 = fig.add_subplot(2, 2, 1); ax1.set_facecolor('#060a0e')
        rad = p.get("radial_activity", []) if p else []
        rmax = float(p.get("radial_range_max", 30.0)) if p else 30.0
        if rad and np.sum(rad) > 0:
            ra = np.asarray(rad, dtype=np.float64); xr = np.linspace(0, rmax, len(ra))
            ax1.fill_between(xr, 0, ra, color='#ff8833', alpha=0.5, step='mid')
            ax1.plot(xr, ra, color='#ffaa33', lw=1.2, drawstyle='steps-mid')
            for tgt in (p.get("df_targets", []) or []):
                ax1.axvline(tgt["range_m"], color='#00ffcc', lw=1.4, alpha=0.9)
                ax1.text(tgt["range_m"], ax1.get_ylim()[1]*0.9,
                         f"{tgt['range_m']:.1f}m\nconf {tgt['confidence']*100:.0f}%",
                         color='#00ffcc', fontsize=6, ha='center', va='top')
            ax1.set_xlabel("range from receiver (m)", color='#aaa', fontsize=8)
            ax1.set_ylabel("device-free motion energy", color='#aaa', fontsize=8)
        else:
            ax1.text(0.5, 0.5, "no device-free motion on any carrier\n(move within the RF field to register)",
                     ha='center', va='center', color='#778', transform=ax1.transAxes, fontsize=9)
        ax1.set_title(f"Device-free RANGE profile (carrier bounces) {_nepa_prov_tag(p)}"
                      f"  · range res ≈ {3e8/(2.0*20e6):.1f} m (20 MHz BW) · bearing UNKNOWN",
                      color='#00ffcc', fontsize=9)
        ax1.tick_params(colors='#666', labelsize=6)

        # Panel 2 — per-carrier Doppler (Kalman link velocity) bar chart
        ax2 = fig.add_subplot(2, 2, 2); ax2.set_facecolor('#060a0e')
        vmap = p.get("rf_carrier_vel", {}) if p else {}
        if vmap:
            items = sorted(vmap.items(), key=lambda kv: abs(kv[1]), reverse=True)[:18]
            labels = [k[-6:] if k != "_link" else "LINK" for k, _ in items]
            vals = [v for _, v in items]
            cols = ['#ff5566' if v < 0 else '#33ddaa' for v in vals]
            ax2.barh(range(len(vals)), vals, color=cols)
            ax2.set_yticks(range(len(vals))); ax2.set_yticklabels(labels, fontsize=5.5, color='#bbb')
            ax2.axvline(0, color='#555', lw=0.6)
            ax2.set_xlabel("carrier RSSI velocity (dBm/s)  — multipath opening/closing", color='#aaa', fontsize=7)
        else:
            ax2.text(0.5, 0.5, "per-carrier velocities building…", ha='center', va='center',
                     color='#778', transform=ax2.transAxes, fontsize=9)
        ax2.set_title(f"Per-carrier Doppler (Kalman) {_nepa_prov_tag(p)}", color='#00ffcc', fontsize=9)
        ax2.tick_params(colors='#666', labelsize=6)

        # Panel 3 — multi-carrier channel sounding: |H(f)| per band + selectivity
        ax3 = fig.add_subplot(2, 2, 3); ax3.set_facecolor('#060a0e')
        cs = p.get("channel_sounding", {}) if p else {}
        bands = cs.get("bands", {}) if cs else {}
        _bcol = {"2.4GHz": "#ff5544", "5GHz": "#33ccff", "6GHz": "#cc66ff", "other": "#aaaaaa"}
        if bands:
            for bn, bd in bands.items():
                ax3.plot(bd["freqs"], bd["mag"], 'o-', ms=4, lw=1.0,
                         color=_bcol.get(bn, "#fff"),
                         label=f"{bn} sel={bd['selectivity']:.2f}")
            ax3.legend(fontsize=6, facecolor='#0a0a0a', labelcolor='#ccc')
            ax3.set_xlabel("Frequency (MHz)", color='#aaa', fontsize=8)
            ax3.set_ylabel("|H(f)| (normalised)", color='#aaa', fontsize=8)
        else:
            ax3.text(0.5, 0.5, "need ≥3 carriers per band for channel sounding",
                     ha='center', va='center', color='#778', transform=ax3.transAxes, fontsize=9)
        ax3.set_title(f"Frequency-selective fading = multipath {_nepa_prov_tag(p)}", color='#00ffcc', fontsize=9)
        ax3.tick_params(colors='#666', labelsize=6)

        # Panel 4 — multipath richness history + honest coherent-IQ hardware path
        ax4 = fig.add_subplot(2, 2, 4); ax4.set_facecolor('#060a0e')
        rh = cs.get("richness_hist", []) if cs else []
        if rh and len(rh) > 1:
            ax4.plot(rh, color='#22ffaa', lw=1.2)
            ax4.fill_between(range(len(rh)), 0, rh, color='#22ffaa', alpha=0.18)
            ax4.set_ylabel("multipath richness", color='#aaa', fontsize=8)
            ax4.set_xlabel("time (frames)", color='#aaa', fontsize=8)
        ax4.set_title(f"Multipath richness over time  (now {cs.get('multipath_richness',0):.3f}) {_nepa_prov_tag(p)}",
                      color='#00ffcc', fontsize=9)
        ax4.tick_params(colors='#666', labelsize=6)

        fig.text(0.5, 0.012,
                 "Coherent-IQ radar — CAF range-Doppler, MUSIC DoA, holographic SAR, and through-wall "
                 "body + heartbeat imaging — needs raw IQ/CSI. Attach an RTL-SDR (~$30) or an ESP32-CSI "
                 "node (~$10): the passive-radar + CSI pipelines are already built and auto-activate on "
                 "connect. Until then everything above is the real magnitude-domain product, no fabrication.",
                 ha='center', color='#99aabb', fontsize=8)

    def _draw_splat(self, fig, p, snap):
        """T3-1/T3-5: free-camera view of the RF reflectivity field via Gaussian splatting,
        with body skeletons overlaid. HONEST SCOPE: this is NOT a photographic copy of the
        room — positions are RSSI range estimates (bearing-limited from few antennas) and the
        splats are coarse reflectivity blobs (~metre scale), not light-like detail."""
        fig.suptitle("NAVIGABLE WORLD — RF reflectivity splats  ·  range-only, bearing-limited · "
                     "NOT photographic (coarse RF estimate)",
                     color='#00ffcc', fontsize=12)
        wr = getattr(self.fuser, "world_recon", None)
        # Main panel: splat render from an orbiting camera around the voxel centre.
        ax1 = fig.add_subplot(1, 2, 1); ax1.set_facecolor('#000')
        if wr is not None:
            res = float(getattr(wr, "voxel_res", 24))
            t = (time.time() * 0.2) % (2 * np.pi)
            centre = np.array([res / 2, res / 2, res / 2])
            cam = centre + np.array([np.cos(t) * res * 1.1, np.sin(t) * res * 1.1,
                                     res * 0.4])
            img = wr.render_splats(cam, centre, width=320, height=240, fov=65.0)
            ax1.imshow(img, origin='upper', interpolation='bilinear')
        ax1.set_title("Gaussian-splat render (orbiting camera)", color='#00ffcc', fontsize=10)
        ax1.axis('off')
        # Side panel: body skeletons + reconstruction status.
        ax2 = fig.add_subplot(1, 2, 2, projection='3d'); ax2.set_facecolor('#050505')
        bodies = list(snap.get("bodies", []) if snap else [])
        _coco = [(0,1),(0,2),(1,3),(2,4),(5,6),(5,7),(6,8),(7,9),(8,10),
                 (5,11),(6,12),(11,12),(11,13),(12,14),(13,15),(14,16)]
        _mesh15 = [(0, 1), (1, 2), (1, 3), (2, 4), (3, 5), (4, 6), (5, 7),
                   (1, 8), (8, 9), (8, 10), (9, 11), (10, 12), (11, 13), (12, 14)]
        _body_sensing = bool(snap.get("body_sensing", False)) if snap else False
        # Fallback: build a body from the live P83 PoseNet joints if no mesh bodies yet —
        # but ONLY when a real body-sensing channel is active (Pass 91: no phantom skeletons).
        if not bodies and _body_sensing:
            pj = snap.get("pose_joints", []) if snap else []
            if pj and len(pj) >= 5:
                bodies = [{"joints": np.asarray(pj), "coco": True}]
        if not _body_sensing:
            ax2.text2D(0.5, 0.5,
                       "NO BODY SENSOR\n\nSkeletons require CSI / mmWave radar.\nNone attached — "
                       "no fabricated bodies shown.",
                       transform=ax2.transAxes, ha='center', va='center',
                       color='#ff8866', fontsize=11, weight='bold')
        cols = ['#00ffcc', '#ffaa22', '#ff55aa', '#55aaff']
        for bi, body in enumerate(bodies):
            J = np.asarray(body["joints"])
            bone_pairs = _coco if (body.get("coco") or len(J) == 17) else _mesh15
            c = cols[bi % len(cols)]
            # Gaussian body splat cloud around each joint (signal-derived volume)
            for jp in J:
                blob = jp + np.random.randn(12, 3) * 0.18
                ax2.scatter(blob[:, 0], blob[:, 1], blob[:, 2], c=c, s=4, alpha=0.18)
            ax2.scatter(J[:, 0], J[:, 1], J[:, 2], c=c, s=22, alpha=0.95)
            for a, b in bone_pairs:
                if a < len(J) and b < len(J):
                    ax2.plot([J[a, 0], J[b, 0]], [J[a, 1], J[b, 1]],
                             [J[a, 2], J[b, 2]], color=c, lw=2)
        # Overlay FMCW points for spatial context
        fmcw_pts = snap.get("fmcw_points", []) if snap else []
        if fmcw_pts is not None and len(fmcw_pts) > 0:
            fp = np.asarray(fmcw_pts)
            ax2.scatter(fp[:, 0], fp[:, 1], fp[:, 2], c='#ff00ff', s=10, alpha=0.5)
        ax2.set_title(f"Body splats ({len(bodies)}) — RF-derived skeletons + FMCW",
                      color='#00ffcc', fontsize=10)
        ax2.tick_params(colors='#666')
        st = (wr.status() if wr is not None else {})
        fig.text(0.5, 0.02,
                 f"NeRF[{st.get('nerf_type','none')}] frames={st.get('nerf_frames',0)}  "
                 f"splats={st.get('splat_count',0)}  open3d={st.get('open3d',False)}  "
                 f"torch={st.get('torch',False)}  keyframes={st.get('keyframes',0)}",
                 ha='center', color='#888', fontsize=9, family='monospace')

    def _draw_instrbus(self, fig, p, snap):
        """v90: MULTI-INSTRUMENT BUS — every connected real instrument + the capabilities it
        contributes, and what additional instrument would unlock each higher-order product.
        A router is the seed; the system grows with whatever hardware is attached (no fixed
        boundary). Shows ONLY real connection state — nothing fabricated."""
        bus = p.get("instrument_bus", {}) if p else {}
        insts = bus.get("instruments", [])
        caps = bus.get("live_capabilities", [])
        fusion = bus.get("fusion", {})
        n_conn = bus.get("instrument_count", 0)
        # v171: provenance-separated counts — simulated is OFFSET from the measured read
        _meas = int(bus.get("measured_count", n_conn))
        _real = int(bus.get("real_count", n_conn))
        _swd  = int(bus.get("software_defined_count", 0))
        _sim  = int(bus.get("simulated_count", 0))
        fig.suptitle(f"MULTI-INSTRUMENT BUS  —  MEASURED {_meas} "
                     f"(real {_real} + software-defined {_swd})"
                     + (f"  ·  SIMULATED {_sim} [watermarked, not measured]" if _sim else ""),
                     color='#00ffcc', fontsize=12, fontweight='bold')

        # ── Panel 1: instrument cards ────────────────────────────────────────
        ax1 = fig.add_subplot(1, 2, 1); ax1.axis('off'); ax1.set_facecolor('#04060a')
        y = 0.98
        ax1.text(0.5, y, "INSTRUMENTS (auto-detected)", ha='center', va='top',
                 transform=ax1.transAxes, color='#00ffcc', fontsize=11, weight='bold')
        y -= 0.07
        _prov_col = {"REAL": '#22ff88', "SOFTWARE-DEFINED": '#33ccff', "SIMULATED": '#ffaa00'}
        for inst in insts:
            conn = inst.get("connected", False)
            prov = inst.get("provenance", "REAL")
            col = (_prov_col.get(prov, '#22ff88') if conn else '#666666')
            dot = '●' if conn else '○'
            ax1.text(0.02, y, f"{dot} {inst.get('kind','?').upper():<14s}",
                     transform=ax1.transAxes, color=col, fontsize=10, weight='bold', va='top')
            # v171: explicit provenance badge so simulated is never read as measured
            _badge = (prov if conn else "not present")
            ax1.text(0.40, y, _badge, transform=ax1.transAxes, color=col, fontsize=8.5,
                     va='top', weight='bold')
            y -= 0.045
            ax1.text(0.06, y, "caps: " + ", ".join(inst.get("capabilities", [])),
                     transform=ax1.transAxes, color='#88ccdd', fontsize=7.5, va='top')
            y -= 0.04
            ax1.text(0.06, y, inst.get("note", ""), transform=ax1.transAxes,
                     color='#999999', fontsize=7, va='top', style='italic')
            y -= 0.062
            if y < 0.04:
                break

        # ── Panel 2: fusion capability matrix (what's unlocked / how to unlock) ──
        ax2 = fig.add_subplot(1, 2, 2); ax2.axis('off'); ax2.set_facecolor('#04060a')
        ax2.text(0.5, 0.98, "FUSED PRODUCTS — live vs upgrade path", ha='center', va='top',
                 transform=ax2.transAxes, color='#00ffcc', fontsize=11, weight='bold')
        _pretty = {"range_only_map": "Range-ring map", "position_fix": "Exact position (x,y)",
                   "wideband_spectrum": "Wideband spectrum", "global_position": "Global position",
                   "velocity": "Target velocity"}
        y = 0.88
        for prod, st in fusion.items():
            avail = st.get("available", False)
            col = '#22ff88' if avail else '#ffaa44'
            mark = "✓ LIVE" if avail else "needs:"
            ax2.text(0.03, y, f"{_pretty.get(prod, prod):<22s}", transform=ax2.transAxes,
                     color='#dddddd', fontsize=9.5, va='top', family='monospace')
            ax2.text(0.55, y, mark, transform=ax2.transAxes, color=col, fontsize=9.5,
                     va='top', weight='bold')
            y -= 0.05
            if not avail:
                for uw in st.get("unlock_with", []):
                    ax2.text(0.10, y, f"↳ connect {uw}", transform=ax2.transAxes,
                             color='#ffcc66', fontsize=8, va='top')
                    y -= 0.04
            y -= 0.02
        # v117: new real-data instruments panel
        _usb_n   = int(p.get("usb_wifi_count", 0)) if p else 0
        _usb_ifs = p.get("usb_wifi_adapters", []) if p else []
        _lan_dev = int(p.get("lan_active_devices", 0)) if p else 0
        _lan_pkt = float(p.get("lan_total_pkt_s", 0.0)) if p else 0.0
        _lan_ifs = p.get("lan_active_ifaces", []) if p else []
        _lan_h   = bool(p.get("lan_presence_hint", False)) if p else False
        _cog_occ2= int(p.get("cog_spec_occupied", 0)) if p else 0
        _cog_tot2= int(p.get("cog_spec_bands", 0)) if p else 0
        _ble_cnt  = sum(1 for i in bus.get("instruments", [])
                        if i.get("kind") == "bluetooth" and i.get("connected"))
        _ble_ents = int(p.get("rf_link_entity_count", 0) or 0)
        _esp32_fr = int(getattr(getattr(self.fuser, "esp32_csi_server", None), "_frames", 0))
        # v119: multi-channel scanner + MDNS discovery stats
        _mc_total = int(p.get("mc_scan_total", 0) if p else 0)
        _mc_new   = int(p.get("mc_scan_new_aps", 0) if p else 0)
        _mc_swps  = int(getattr(getattr(self.fuser, "multi_chan_scanner", None),
                                "_sweeps_done", 0))
        _mdns_tot = int(p.get("mdns_total", 0) if p else 0)
        _mdns_new = int(p.get("mdns_new_nodes", 0) if p else 0)
        _avahi_ok = getattr(getattr(self.fuser, "mdns_discovery", None), "_avahi_ok", None)
        _mdns_src = "avahi" if _avahi_ok else ("ARP" if _avahi_ok is False else "scanning…")
        # v123 instrument metrics
        _gpsd_ok  = bool(getattr(getattr(self.fuser, "gpsd_client", None), "ok", False))
        _gps_fix  = p.get("gps_fix", {}) if p else {}
        _acou_ok  = bool(getattr(getattr(self.fuser, "acoustic_doppler", None), "has_mic", False))
        _acou_mot = float((p.get("acoustic_sensor", {}) or {}).get("motion", 0.0))
        _therm_ok = bool(getattr(getattr(self.fuser, "thermal_presence", None), "ok", False))
        _therm_t  = float((p.get("thermal_sensor", {}) or {}).get("max_temp_c", 0.0))
