                ax4.set_xlabel("x (m)", color='#888', fontsize=7)
                ax4.set_ylabel("z (m)", color='#888', fontsize=7)
                ax4.set_title(f"Omega-K SAR MIP ({len(_ok_peaks)} peaks)", color='#ff8844', fontsize=9)
