    def _open_entity_windows(self, max_windows=8):
        """v101: open ONE pop-up detail window per detected entity (bodies + real RF carriers),
        directly fulfilling 'each body/instrument in its own tab'. Capped to avoid flooding."""
        try:
            ents = DetailTabWindow._entity_list(self.psych_profile)
            if not ents:
                log.info("[TAB] no entities to open (no bodies/RF carriers detected yet)")
                return
            if not hasattr(self, "_detail_tabs"):
                self._detail_tabs = {}
            for ent in ents[:max_windows]:
                ekey = ent.get("_key", "?")
                tabkey = f"entitydetail:{ekey}"     # v108: keyed by STABLE entity id, not index
                if tabkey not in self._detail_tabs:
                    w = DetailTabWindow(self, kind="entitydetail", entity_key=ekey)
                    self._detail_tabs[tabkey] = w
                    w.launch()
            log.info(f"[TAB] opened {min(len(ents), max_windows)} per-entity windows "
                     f"({len(ents)} entities live)")
        except Exception as e:
            log.warning(f"[TAB] per-entity windows failed: {e}")

    def _open_tab(self, kind):
        """Pass 27: open a view tab in its own window (idempotent — re-raises if open)."""
        try:
            if kind == "world":
                if getattr(self, "world_viewer", None) is None:
                    self.world_viewer = World3DViewer(self)
                    self.world_viewer.launch()
            elif kind == "instruments":
                if getattr(self, "instrument_viewer", None) is None:
                    self.instrument_viewer = InstrumentMeshViewer(self)
                    self.instrument_viewer.launch()
            else:
                if not hasattr(self, "_detail_tabs"):
                    self._detail_tabs = {}
                if kind not in self._detail_tabs:
                    self._detail_tabs[kind] = DetailTabWindow(self, kind=kind)
                    self._detail_tabs[kind].launch()
            log.info(f"[TAB] opened '{kind}'")
        except Exception as e:
            log.warning(f"[TAB] open '{kind}' failed: {e}")

