    # v300++++: standalone PHYSICS verification — prove the core sensing math is exact.
    if getattr(args, "physics_test", False):
        _ph = PhysicsAccuracyHarness(bw_hz=20e6, n_sub=64)
        _rep = _ph.run()
        log.info(f"[PHYSICS] range resolution = {_rep['range_resolution_m']} m  (c/2·BW, BW=20 MHz)  "
                 f"· max unambiguous = {_rep['max_unambiguous_range_m']} m")
        for _t in _rep["single_target_tests"]:
            log.info(f"[PHYSICS]  reflector {_t['true_m']:>5} m → recovered {_t['est_m']:>6} m  "
                     f"(error {_t['error_m']} m ≤ res {_t['range_res_m']} m: "
                     f"{'PASS' if _t['within_resolution'] else 'FAIL'})")
        _rl = _rep["resolution_limit_test"]
        log.info(f"[PHYSICS]  two reflectors >1 cell apart → {_rl['separable_pair_peaks']} peaks "
                 f"({'PASS' if _rl['separable_ok'] else 'FAIL'}); <1 cell apart → "
                 f"{_rl['unresolvable_pair_peaks']} peak ({'PASS' if _rl['merge_ok'] else 'FAIL'} — limit is real)")
        log.info(f"[PHYSICS]  MATH CORRECT (recovers truth within the physical limit): {_rep['math_correct']}")
        log.info("[PHYSICS]  NOTE: this proves the COMPUTATION is exact. Reconstruction FIDELITY is "
                 "still hardware-bounded (bandwidth→range, aperture→bearing); a single antenna gives no bearing.")
        sys.exit(0 if _rep["math_correct"] else 1)

    # v300+++ (#1): standalone self-test mode — verify the additive subsystems and exit.
    if getattr(args, "self_test", False):
        _st = NEPASelfTestSuite(globals()).run()
        for _r in _st["results"]:
            log.info(f"[SELFTEST] {'PASS' if _r['pass'] else 'FAIL'}  {_r['test']}  {_r['detail']}")
        log.info(f"[SELFTEST] {_st['passed']}/{_st['total']} passed")
        sys.exit(0 if _st["all_pass"] else 1)

    # v300+++ (#8): apply the global seed as early as possible for reproducibility.
    if getattr(args, "seed", None) is not None:
        try:
            import random as _rnd
            _rnd.seed(args.seed)
            np.random.seed(int(args.seed) % (2 ** 32 - 1))
            log.info(f"[DETERMINISM] global seed = {args.seed}")
        except Exception:
            pass
    # Pass 44: T-RECORD frame recorder init
    _splat_recorder_global = None
    if getattr(args, 'record_splat', None):
        _splat_recorder_global = SplatFrameRecorder(record_dir=args.record_splat, fmt='auto')
        log.info(f"[RECORD] Frame recorder active → {args.record_splat}")

    # List 1.9: offline training mode (no UI)
    if args.train:
        mlp = TinyMLP()
        mlp = offline_train(args.record_path, mlp, epochs=args.epochs)
        with open('nepa_mlp.pkl', 'wb') as fh:
            pickle.dump({'W1': mlp.W1, 'b1': mlp.b1, 'W2': mlp.W2, 'b2': mlp.b2}, fh)
        log.info("[TRAIN] Saved fine-tuned MLP to nepa_mlp.pkl")
        sys.exit(0)

    # v300+ (#6): standalone receiver-mesh node mode — no UI, just stream signed
    # observations to a SecureMeshIngestServer. Turns any laptop/Pi into a real
    # mesh sensor (the missing 'sender' that makes the multistatic mesh real).
    if getattr(args, "mesh_node", None):
        try:
            _pos = tuple(float(x) for x in str(args.node_pos).split(","))
        except Exception:
            _pos = (0.0, 0.0, 0.0)
        _node = ReceiverNodeClient(args.mesh_node, secret=getattr(args, "node_secret", None),
                                   position=_pos)
        try:
            _node.run()
        except KeyboardInterrupt:
            pass
        sys.exit(0)

    mode = 'sim' if args.demo_only else args.mode
    fuser = MultiAgentWirelessBCIFuser(mode=mode, udp_port=args.port,
                                       demo_only=args.demo_only,
                                       record=args.record, record_path=args.record_path,
                                       sim_validate=args.sim_validate)
    fuser.enable_world = not args.no_world   # Pass 25: walkable 3D world toggle
    fuser.target_fps = max(5, min(60, args.fps))  # Pass 26: live refresh rate
    # v116 BUGFIX: --record-splat created a SplatFrameRecorder + dir but was never wired to the
    # fuser and save_frame() was never called → it recorded ZERO frames (non-implemented feature).
    # Wire it so the main loop actually saves rendered splat frames.
    fuser.splat_recorder = _splat_recorder_global
    # v94: simulate-hardware (virtual instruments). Watermarked SIMULATED everywhere.
    if getattr(args, "simulate_hardware", False):
        fuser.sim_hardware = True
        try:
            fuser.instrument_bus.set_simulation(True)
        except Exception:
            pass
        log.info("[MAIN] SIMULATE-HARDWARE ON — virtual CSI/SDR/GPR instruments registered "
                 "(all outputs watermarked SIMULATED, never shown as real).")
    # Pass 30 (T0-5): enable passive-sniff CSI capture path.
    if args.passive_sniff and hasattr(fuser, "router_csi"):
        fuser.router_csi.enable_passive_sniff(monitor_iface=args.monitor_iface)
        log.info("[MAIN] Passive-sniff capture path enabled.")

    # Pass 34 (T-WEB): --web-viewer HTTP MJPEG stream of the Gaussian-splat world
    if args.web_viewer:
        fuser.web_viewer = WebViewerServer(fuser, port=args.web_port)
        fuser.web_viewer.start()

    # v104: --ingest-port multi-node REAL-DATA ingest server (distributed real sensors)
    if getattr(args, "ingest_port", 0):
        fuser.ingest_server = RemoteSensorIngestServer(fuser, port=args.ingest_port)
        fuser.ingest_server.start()

    # v118: --csi-port ESP32 real per-subcarrier CSI ingest (any ESP32 + esp-csi firmware)
    if getattr(args, "csi_port", 0):
        fuser.esp32_csi_server = ESP32CSIIngestServer(fuser, port=args.csi_port)
        fuser.esp32_csi_server.start()

    # Pass 34 (T-LSL): --lsl BCI band-power LSL outlet
    if args.lsl:
        fuser.lsl_broadcaster = BCILSLBroadcaster(
            srate=float(max(5, min(60, args.fps))))

    # Pass 34 (T-SEM): --mqtt-host for SemanticStateEngine MQTT publishing
    if args.mqtt_host:
        fuser.semantic_engine = SemanticStateEngine(
            room_id="room_0",
            mqtt_host=args.mqtt_host,
            mqtt_port=args.mqtt_port,
            ha_discovery=args.ha_discovery,
        )
        log.info(f"[MAIN] SemanticStateEngine MQTT → {args.mqtt_host}:{args.mqtt_port}")

    # v300: Capability Expansion Pack (#1-#10) — ADDITIVE. Adds new subsystems
    # alongside the existing pipeline; removes/replaces nothing. The Claude
    # overseer (#9) is OFF unless --llm-overseer is passed (it makes outbound,
    # billable network calls). Wired via the same opt-in pattern as the other
    # optional features above.
    if not getattr(args, "no_power_pack", False):
        try:
            fuser.power_pack = NEPACapabilityExpansionPackV23(
                fuser, args, namespace=globals(),
                llm_overseer=getattr(args, "llm_overseer", False),
                llm_model=getattr(args, "llm_model", "claude-opus-4-8"))
            fuser.power_pack.attach()
        except Exception as _ppe:
            log.warning(f"[POWERPACK] init failed (non-fatal — base system unaffected): {_ppe}")

    # v300++++: --ground-truth registers a known emitter so live reconstruction RMSE is measured.
    if getattr(args, "ground_truth", None) and getattr(fuser, "power_pack", None) is not None:
        try:
            _gt = [float(x) for x in str(args.ground_truth).split(",")]
            fuser.power_pack.validation.set_ground_truth("ground_truth", _gt)
            log.info(f"[GROUND-TRUTH] registered known emitter 'ground_truth' at {_gt} m — live RMSE "
                     f"logged when a fix named 'ground_truth' is produced (name your test device's "
                     f"emitter accordingly, or have a mesh node report it).")
        except Exception as _gte:
            log.warning(f"[GROUND-TRUTH] bad --ground-truth '{args.ground_truth}': {_gte}")

    # v300+ (#2): optional UDP capture→fusion decoupler (drop-stale). Wired only on
    # the UDP path (its _process_frame return value is unused there). Off by default.
    if getattr(args, "turbo_udp", False):
        try:
            fuser._turbo_udp = TurboFrameAccelerator(fuser._process_frame)
            fuser._turbo_udp.start()
            log.info("[POWERPACK] #2 turbo-udp decoupler active (latest-wins, drop-stale).")
        except Exception as _te:
            log.warning(f"[POWERPACK] turbo-udp init failed: {_te}")

    try:
        fuser.start()
    except KeyboardInterrupt:
        # start()'s finally block already sets running=False and saves recorder/profiles
        log.info("N.E.P.A. v23 shutdown complete. Humanitarian life-saving system delivered.")                                                                                                                      